    diffs = [A[i + 1] - A[i] for i in range(DMAX - 1)]
    rdiff = {}
    for i in range(1, DMAX - 1):
        rdiff[f"d{i+1}"] = (float(diffs[i] / diffs[i - 1])
                            if diffs[i - 1] != 0 else None)
