            A_v1=A, mean_L=mL, mean_R=mR,
            p_two=p, p_up=p_up, null_mode=mode, null_n=nn,
            null_floor=floor, null_mean=_nm, null_sd=_ns, null_median=_nmed,
            null_p05=float(np.percentile(nd, 5)),
